// Executed inside the authenticated MAM n8n Code node; tested without network.
const HR = 'hr@mobilityaccess.com.au';
const ACCOUNTS = 'accounts@mobilityaccess.com.au';
const EMAIL = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;
const APP_URL = 'https://mam-team-management-system-ten.vercel.app';
const EVENTS = ['payroll-comparison-alert', 'leave-submitted', 'leave-approved', 'leave-declined', 'leave-cancelled', 'leave-conditionally-approved', 'leave-reminder', 'team-birthday', 'payroll-balance-reminder'];
const STATUSES = ['Pending', 'Approved', 'Declined', 'Cancelled', 'Approved – pending leave balance'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
const TIME = /^(?:[01]\d|2[0-3]):[0-5]\d$/;
const TTL = 90 * 24 * 60 * 60 * 1000;
const PROCESSING = 20 * 60 * 1000;
const reject = (code) => [{ json: { outcome: 'rejected', ok: false, sent: false, alreadySent: false, rejectionCode: code } }];
const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = (value, max) => typeof value === 'string' && value.length > 0 && value.length <= max
  && value === value.trim() && !/[\u0000-\u001f\u007f]/.test(value);
const optionalText = (value, max) => value === null || value === undefined || (typeof value === 'string'
  && value.length <= max && value === value.trim() && !/[\u0000-\u001f\u007f]/.test(value));
// Notes are body content, not headers: allow normal textarea whitespace.
const optionalNote = (value, max) => value === null || value === undefined || (typeof value === 'string'
  && value.length <= max && value === value.trim() && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value));
const escape = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const validDate = (value) => {
  if (!DATE.test(String(value))) return false;
  const date = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(date.valueOf()) && date.toISOString().slice(0, 10) === value;
};
const friendlyDate = (value) => {
  const [year, month, day] = value.split('-').map(Number);
  return new Intl.DateTimeFormat('en-AU', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Australia/Melbourne' })
    .format(new Date(Date.UTC(year, month - 1, day, 12)));
};
const friendlyMonth = (value) => {
  const [year, month] = value.split('-').map(Number);
  return new Intl.DateTimeFormat('en-AU', { month: 'long', year: 'numeric', timeZone: 'Australia/Melbourne' })
    .format(new Date(Date.UTC(year, month - 1, 1, 12)));
};
const emailList = (value) => {
  const raw = Array.isArray(value) ? value : typeof value === 'string' ? value.split(/[;,]/) : [];
  const emails = raw.map((email) => String(email).trim().toLowerCase()).filter((email) => EMAIL.test(email));
  return [...new Set(emails)];
};
try {
  const input = $input.first().json ?? {};
  const headers = object(input.headers) ? input.headers : {};
  const body = object(input.body) ? input.body : null;
  const required = ['version', 'event', 'eventKey', 'requestId', 'employeeName', 'employeeEmail', 'company', 'leaveType',
    'startDate', 'endDate', 'startTime', 'endTime', 'days', 'hours', 'status', 'employeeNote', 'managerNote', 'managerEmail'];
  if (!String(headers['content-type'] ?? '').toLowerCase().startsWith('application/json')) return reject('content-type');
  if (!body || body.version !== 1 || !EVENTS.includes(body.event) || JSON.stringify(body).length > 20000) return reject('body-shape');
  if (body.event === 'payroll-comparison-alert') {
    if (Object.keys(body).length !== 5 || !UUID.test(String(body.batchId))
      || body.eventKey !== `payroll-comparison:${body.batchId}`
      || !Number.isInteger(body.differenceCount) || body.differenceCount < 1 || body.differenceCount > 2000) return reject('comparison-shape');
    const recipient = 'marketing@mobilityaccess.com.au';
    const state = $getWorkflowStaticData('global');
    if (!object(state.leaveNotificationEvents)) state.leaveNotificationEvents = {};
    const previous = state.leaveNotificationEvents[body.eventKey];
    if (previous?.state === 'sent') return [{ json: { outcome: 'duplicate', ok: true, sent: false, alreadySent: true, actualRecipient: recipient, eventKey: body.eventKey } }];
    if (previous?.state === 'processing' && Date.now() - previous.at < PROCESSING) return reject('delivery-in-flight');
    state.leaveNotificationEvents[body.eventKey] = {state:'processing',at:Date.now()};
    return [{json:{outcome:'send',mamDelivery:true,deliveryRecipient:recipient,confirmationRecipient:recipient,ccRecipients:'',eventKey:body.eventKey,
      emailSubject:'[People Hub] Leave balance differences require review',
      emailHtml:'<p>A payroll upload has ' + body.differenceCount + ' leave balance differences or unmatched entries.</p><p>Existing balances have not been changed.</p><p>Open Leave → Balance → Recent imports to review uploaded and system balances.</p><p>Reference: ' + escape(body.batchId) + '</p><p><a href="' + APP_URL + '/?view=leave">People Hub</a></p>'}}];
  }
  if (body.event === 'payroll-balance-reminder') {
    const payrollRequired = ['version', 'event', 'eventKey', 'requestId', 'recipientName', 'recipientEmail', 'reminderMonth', 'missingCompanies'];
    if (Object.keys(body).length !== payrollRequired.length
      || !payrollRequired.every((key) => Object.prototype.hasOwnProperty.call(body, key))) return reject('payroll-body-shape');
    if (!UUID.test(String(body.requestId))) return reject('request-id');
    if (!validDate(body.reminderMonth) || !String(body.reminderMonth).endsWith('-01')) return reject('payroll-month');
    if (String(body.eventKey) !== `payroll-balance:${body.requestId}:${body.reminderMonth.slice(0, 7)}`) return reject('event-key');
    if (!text(body.recipientName, 80)
      || typeof body.recipientEmail !== 'string'
      || body.recipientEmail !== body.recipientEmail.trim().toLowerCase()
      || body.recipientEmail.length > 254
      || !EMAIL.test(body.recipientEmail)) return reject('payroll-recipient');
    if (!Array.isArray(body.missingCompanies)
      || body.missingCompanies.length < 1
      || body.missingCompanies.length > 2
      || new Set(body.missingCompanies).size !== body.missingCompanies.length
      || body.missingCompanies.some((company) => !['mam', 'equipsy'].includes(company))) return reject('payroll-companies');

    const now = Date.now();
    const state = $getWorkflowStaticData('global');
    const raw = object(state.leaveNotificationEvents) ? state.leaveNotificationEvents : {};
    const events = {};
    for (const [key, value] of Object.entries(raw)) {
      if (object(value) && Number.isFinite(value.at) && now - value.at <= TTL && Object.keys(events).length < 5000) {
        events[key] = { state: value.state === 'sent' ? 'sent' : 'processing', at: value.at };
      }
    }
    state.leaveNotificationEvents = events;
    const previous = events[body.eventKey];
    if (previous?.state === 'sent') return [{ json: { outcome: 'duplicate', ok: true, sent: false, alreadySent: true,
      actualRecipient: body.recipientEmail, eventKey: body.eventKey } }];
    if (previous?.state === 'processing' && now - previous.at < PROCESSING) return reject('delivery-in-flight');
    events[body.eventKey] = { state: 'processing', at: now };

    const companyLabels = body.missingCompanies.map((company) => company === 'mam' ? 'MAM' : 'Equipsy');
    const monthLabel = friendlyMonth(body.reminderMonth);
    const emailHtml = [
      '<p>Hi ' + escape(body.recipientName) + ',</p>',
      '<p>The ' + escape(monthLabel) + ' banked leave balance update is due.</p>',
      '<p><strong>Still required:</strong> ' + escape(companyLabels.join(' and ')) + '</p>',
      '<p>Upload the latest CSV or Excel leave-balance files in People Hub.</p>',
      '<p><a href="' + APP_URL + '/?view=leave" style="display:inline-block;padding:10px 16px;background:#ef6c24;color:#fff;text-decoration:none;border-radius:6px;font-weight:600">Open payroll balance upload</a></p>',
    ].join('');
    return [{ json: { outcome: 'send', mamDelivery: true, deliveryRecipient: body.recipientEmail,
      confirmationRecipient: body.recipientEmail, ccRecipients: '', eventKey: body.eventKey,
      emailSubject: `[MAM] Monthly banked leave update due — ${monthLabel}`, emailHtml } }];
  }
  if (!required.every((key) => Object.prototype.hasOwnProperty.call(body, key))) return reject('body-shape');
  if (!UUID.test(String(body.requestId))) return reject('request-id');
  const eventEscaped = String(body.event).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (!new RegExp(`^leave:${body.requestId}:${eventEscaped}:[0-9a-f]{24}$`, 'i').test(String(body.eventKey))) return reject('event-key');
  if (!text(body.employeeName, 160) || !['mam', 'equipsy'].includes(body.company) || !text(body.leaveType, 120)) return reject('employee-data');
  if (!validDate(body.startDate) || !validDate(body.endDate) || body.endDate < body.startDate) return reject('dates');
  if (!optionalText(body.startTime, 5) || (body.startTime !== null && !TIME.test(body.startTime))) return reject('start-time');
  if (!optionalText(body.endTime, 5) || (body.endTime !== null && !TIME.test(body.endTime))) return reject('end-time');
  if (!['number', 'object'].includes(typeof body.days) || (body.days !== null && (!Number.isFinite(body.days) || body.days <= 0))) return reject('days');
  if (!['number', 'object'].includes(typeof body.hours) || (body.hours !== null && (!Number.isFinite(body.hours) || body.hours <= 0))) return reject('hours');
  if (body.fullDayHours !== undefined && (!Number.isFinite(body.fullDayHours) || body.fullDayHours <= 0 || body.fullDayHours > 24)) return reject('full-day-hours');
  if (!STATUSES.includes(body.status) || !optionalNote(body.employeeNote, 4000) || !optionalNote(body.managerNote, 4000)) return reject('status-or-notes');
  const managerEmails = typeof body.managerEmail === 'string' ? body.managerEmail.split(',') : [];
  if (!(body.managerEmail === null || (managerEmails.length > 0 && managerEmails.length <= 10
    && managerEmails.every((email) => email.length <= 254 && EMAIL.test(email))))) return reject('manager-email');
  const managers = [...new Set(managerEmails.map((email) => email.toLowerCase()))];
  const employeeEmails = emailList(Array.isArray(body.employeeEmails) ? body.employeeEmails : body.employeeEmail);
  const sick = body.leaveType === 'Sick leave' || body.leaveType === "Carer's leave";
  const split = body.audience !== undefined;
  // Old application instances leave their event queued until the split-aware
  // dispatcher retries. Never fall back to exposing applicant addresses in To.
  if (body.event === 'leave-submitted' && !split) return reject('audience-required');
  if (split && (body.event !== 'leave-submitted' || !['employee', 'reviewers'].includes(body.audience))) return reject('audience');
  if (body.legacyEventKey !== undefined && (!split
    || !new RegExp(`^leave:${body.requestId}:leave-submitted:[0-9a-f]{24}$`, 'i').test(String(body.legacyEventKey))
    || body.legacyEventKey === body.eventKey)) return reject('legacy-event-key');
  const snapshot = body.leaveBalance;
  if (snapshot !== undefined && snapshot !== null && (!object(snapshot)
    || snapshot.kind !== (sick ? 'sick' : 'annual') || (!sick && body.leaveType !== 'Annual leave')
    || !['current', 'check_balance'].includes(snapshot.status)
    || (snapshot.hours !== null && !Number.isFinite(snapshot.hours))
    || (snapshot.status === 'check_balance' && snapshot.hours !== null))) return reject('leave-balance');
  const employeeDelivery = body.audience === 'employee' || ['leave-approved', 'leave-declined', 'leave-conditionally-approved'].includes(body.event);
  const managerDelivery = ['leave-submitted', 'leave-cancelled', 'leave-reminder', 'team-birthday'].includes(body.event);
  if (employeeDelivery && employeeEmails.length === 0) return reject('employee-email');
  if (managerDelivery && managers.length === 0) return reject('manager-email');
  const now = Date.now();
  const state = $getWorkflowStaticData('global');
  const raw = object(state.leaveNotificationEvents) ? state.leaveNotificationEvents : {};
  const events = {};
  for (const [key, value] of Object.entries(raw)) {
    if (object(value) && Number.isFinite(value.at) && now - value.at <= TTL && Object.keys(events).length < 5000) {
      events[key] = { state: value.state === 'sent' ? 'sent' : 'processing', at: value.at };
    }
  }
  state.leaveNotificationEvents = events;
  const reviewers = [...new Set([...managers, HR])].filter((email) => !employeeEmails.includes(email));
  const confirmationRecipient = split ? (body.audience === 'employee' ? employeeEmails : reviewers).join(',')
    : managerDelivery ? managers.join(',') : employeeEmails.join(',');
  if (!confirmationRecipient) return reject('recipient');
  const deliveryRecipient = confirmationRecipient;
  const ccRecipients = split || body.event === 'leave-reminder' || body.event === 'team-birthday' ? '' : [HR, ...(body.event === 'leave-approved' || (body.event === 'leave-cancelled' && body.wasApproved !== false) ? [ACCOUNTS] : [])].filter((email) => !deliveryRecipient.split(',').includes(email)).join(',');
  // During rollout, a shared send may already have succeeded while its DB
  // acknowledgement failed. Its receipt covers both new copies; do not resend.
  const legacy = body.legacyEventKey ? events[body.legacyEventKey] : undefined;
  if (legacy?.state === 'sent') return [{ json: { outcome: 'duplicate', ok: true, sent: false,
    alreadySent: true, actualRecipient: confirmationRecipient, eventKey: body.eventKey } }];
  if (legacy?.state === 'processing' && now - legacy.at < PROCESSING) return reject('delivery-in-flight');
  const previous = events[body.eventKey];
  if (previous?.state === 'sent') return [{ json: { outcome: 'duplicate', ok: true, sent: false, alreadySent: true, actualRecipient: confirmationRecipient, eventKey: body.eventKey } }];
  if (previous?.state === 'processing' && now - previous.at < PROCESSING) return reject('delivery-in-flight');
  events[body.eventKey] = { state: 'processing', at: now };
  const eventLabel = { 'leave-submitted': 'submitted', 'leave-approved': 'approved', 'leave-declined': 'declined', 'leave-cancelled': 'cancelled', 'leave-conditionally-approved': 'approved, subject to sufficient leave balance', 'leave-reminder': body.status === 'Approved – pending leave balance' ? 'approved, subject to sufficient leave balance — awaiting your review' : 'awaiting your review', 'team-birthday': 'team birthday reminder' }[body.event];
  const employeeCopy = body.event === 'leave-conditionally-approved' ? 'Your ' + body.leaveType.toLowerCase() + ' request has been approved, subject to sufficient leave balance.' : body.event === 'leave-approved' ? 'Your leave request has been approved.' : body.event === 'leave-declined' ? 'Your leave request has been declined.' : 'This is a record of your leave request.';
  const managerCopy = body.event === 'leave-reminder' ? (body.status === 'Approved – pending leave balance' ? 'This leave request is approved, subject to sufficient leave balance. Please review the balance and finalise approval.' : 'Please review this outstanding leave request.') : body.event === 'leave-submitted' ? 'A leave request is waiting for your review.' : 'This is a record of the leave request being ' + eventLabel + '.';
  const employeeDeliveryLink = APP_URL + '/?view=leave&request=' + encodeURIComponent(body.requestId);
  const managerDeliveryLink = APP_URL + '/?view=leave&section=approvals&request=' + encodeURIComponent(body.requestId);
  const requestedHours = body.hours ?? (body.days === null ? null : body.days * (body.fullDayHours ?? 7.5));
  const hoursLabel = (value) => new Intl.NumberFormat('en-AU', { maximumFractionDigits: 2 }).format(value) + ' hours';
  const emailStatus = body.status === 'Approved – pending leave balance' ? 'Approved, subject to sufficient leave balance' : body.status;
  const emailHtml = body.event === 'team-birthday' ? '<p>Team birthday reminder: <strong>' + escape(body.employeeName) + '</strong></p><p>Birthday: ' + escape(friendlyDate(body.startDate)) + '</p><p><a href="' + APP_URL + '">People Hub</a></p>' : [
    '<p>' + (employeeDelivery ? 'Hi ' + escape(body.employeeName) + ',' : 'MAM leave notification') + '</p>',
    '<p>' + escape(body.event === 'leave-submitted' ? 'A leave request has been submitted and is awaiting review.' : employeeDelivery ? employeeCopy : managerCopy) + '</p>',
    '<p><strong>Leave request details</strong></p>', '<ul>',
    '<li><strong>Employee:</strong> ' + escape(body.employeeName) + '</li>',
    '<li><strong>Company:</strong> ' + escape(body.company) + '</li>',
    '<li><strong>Leave type:</strong> ' + escape(body.leaveType) + '</li>',
    '<li><strong>Dates:</strong> ' + escape(friendlyDate(body.startDate)) + ' – ' + escape(friendlyDate(body.endDate)) + '</li>',
    body.startTime ? '<li><strong>Start time:</strong> ' + escape(body.startTime) + '</li>' : '',
    body.endTime ? '<li><strong>End time:</strong> ' + escape(body.endTime) + '</li>' : '',
    body.days !== null ? '<li><strong>Business days:</strong> ' + escape(body.days) + '</li>' : '',
    requestedHours !== null && body.event === 'leave-submitted' ? '<li><strong>Hours requested:</strong> ' + hoursLabel(requestedHours) + '</li>' : body.hours !== null ? '<li><strong>Hours:</strong> ' + escape(body.hours) + '</li>' : '',
    '<li><strong>Status:</strong> ' + escape(emailStatus) + '</li>', '</ul>',
    employeeDelivery && body.managerNote && !emailList([deliveryRecipient,ccRecipients].join(',')).includes(ACCOUNTS.toLowerCase()) ? '<p><strong>Manager note:</strong> ' + escape(body.managerNote) + '</p>' : '',
    '<p><a href="' + (body.event === 'leave-submitted' && !split ? APP_URL : employeeDelivery ? employeeDeliveryLink : managerDeliveryLink) + '" style="display:inline-block;padding:10px 16px;background:#ef6c24;color:#fff;text-decoration:none;border-radius:6px;font-weight:600">People Hub</a></p>',
  ].join('');
  return [{ json: { outcome: 'send', mamDelivery: body.company === 'mam', deliveryRecipient, confirmationRecipient, ccRecipients, eventKey: body.eventKey,
    emailSubject: body.event === 'team-birthday' ? `[MAM] Team birthday reminder: ${body.employeeName}` : employeeDelivery ? `[MAM] Leave ${eventLabel}: ${body.leaveType}` : `[MAM] Leave ${eventLabel}: ${body.employeeName} — ${body.leaveType}`,
    emailHtml } }];
} catch { return reject('exception'); }

const source = $('Validate and Reserve Leave Notification').all();
const sent = $input.all();
if (sent.some(item=>{const r=item.json||{};const status=Number(r.statusCode||r.status);return r.error||r.success===false||r.ok===false||(Number.isFinite(status)&&status>=400);})) throw new Error('Email provider explicitly rejected delivery.');

const eventKey = String(source[0]?.json?.eventKey ?? '');
if (source.length !== 1 || sent.length !== 1 || !(eventKey.startsWith('leave:') || eventKey.startsWith('payroll-balance:') || eventKey.startsWith('payroll-comparison:'))) throw new Error('MAM email delivery count mismatch.');
const state = $getWorkflowStaticData('global');
if (!state.leaveNotificationEvents || typeof state.leaveNotificationEvents !== 'object') state.leaveNotificationEvents = {};
state.leaveNotificationEvents[eventKey] = { state: 'sent', at: Date.now() };
return [{ json: {
  ok: true, sent: true, alreadySent: false,
  actualRecipient: String(source[0].json.deliveryRecipient ?? ''),
  eventKey,
} }];
